{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Atazanavir, a peptidomimetic HIV protease inhibitor with carbamate and aromatic substituents, has an oral bioavailability of 69% under fasting conditions in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Darunavir, a carbamate-containing HIV protease inhibitor, has an oral bioavailability of 37% when given alone in patients, exceeding the 20% threshold despite first-pass metabolism and P-gp efflux liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "KNI-272, a peptidomimetic HIV protease inhibitor with heteroaryl/thiazolidine motifs, has an absolute oral bioavailability of 33.99 ± 9.73% in fasting patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Amprenavir, a carbamate/sulfonamide HIV protease inhibitor, is reported to have a bioavailability range of 35–90% in HIV-infected patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Lopinavir, the closest analogue sharing the hydroxyethylene core and valine, is described as having very low oral bioavailability in humans due to CYP3A first-pass metabolism and P-gp efflux, arguing for possible F < 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "CGP 38 560, a hydroxyethylene peptidomimetic renin inhibitor, had <1% oral bioavailability in humans, providing a low-F example with a similar core but lower structural transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: although the closest analogue lopinavir has very low oral bioavailability, multiple direct human measurements in structurally related HIV protease inhibitors with carbamate/heteroaryl features (atazanavir 69% fasting, darunavir 37%, amprenavir 35–90%, KNI-272 ~34%) support F ≥ 20%; the query's thiazole carbamate/urea termini resemble these higher-bioavailability compounds more than the poorly absorbed renin inhibitors.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Lopinavir's low bioavailability is reported qualitatively and may not be precisely threshold-relevant for F < 20%.",
    "No human data are available for the exact combination of a hydroxyethylene core with thiazole carbamate/urea termini."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

